        (bool ok, ) = address(c).call{value: fundAmount}("");
        require(ok);
        uint256 balanceBefore = address(c).balance;
        // Self-directed multiplicate: if amount >= balanceBefore, C transfers
        // its entire new balance to itself (a no-op net effect); otherwise the
        // function body does nothing. Either way C ends with balanceBefore + amount.
        c.multiplicate{value: amount}(address(c));
        assert(address(c).balance == balanceBefore + amount);
    }
